use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        let mut fields: Vec<string> = []
        let mut cur = ""
        let mut in_q = false
        let mut pending = false
        for c in line.chars() {
            if c == '"' {
                if in_q {
                    in_q = false
                    pending = true
                } else {
                    in_q = true
                    if pending {
                        cur = cur + "\""
                    }
                    pending = false
                }
            } else if c == ',' && !in_q {
                fields.push(cur)
                cur = ""
                pending = false
            } else if c == '\r' {
                pending = false
            } else {
                pending = false
                cur = cur + c.to_string()
            }
        }
        fields.push(cur)
        let n: int = fields.len() as int
        let mut out = "${n}: "
        let mut first = true
        for f in fields {
            if !first {
                out = out + "|"
            }
            first = false
            out = out + "[" + f + "]"
        }
        println(out)
    }
}

